 * tsconfig and its `@/` alias. It imports `src/content/archive.ts` and `src/copy.ts` exactly as
 * the site's pages do, so what reaches the table is what the site would have built, mapped by the
 * one file that knows how that publication's stills, plates or objects are laid out. Nothing here
 * re-derives a path or a slug: ops/refresh.mjs is explicit that the four ingests are not
 * interchangeable, and a dump that reimplemented one of them would be silently right on the site
 * it was written against and silently wrong on the other three.
 *
 * The one thing the contract does not carry is the LANE's id for an entry, and the permalink
 * lives under that id in state.<lane>.json. The raw JSON beside the adapter carries it, keyed by
 * the hook the adapter copied verbatim, so the id is looked up by hook here and settled by the
 * id suffix the adapters put into a colliding slug.
 */
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

const site = process.cwd();
const archive = (await import(pathToFileURL(path.join(site, "src/content/archive.ts")).href)).default;
const { COPY } = await import(pathToFileURL(path.join(site, "src/copy.ts")).href);

type Raw = { id?: string; hook?: string; title?: string; slug?: string };
const rawPath = ["src/content/entries.json", "src/content/phenomena.json"]
  .map((p) => path.join(site, p))
  .find((p) => fs.existsSync(p));
const rawFile = rawPath ? JSON.parse(fs.readFileSync(rawPath, "utf8")) : [];
const raw: Raw[] = Array.isArray(rawFile) ? rawFile : rawFile.phenomena ?? [];

const byHook = new Map<string, Raw[]>();
for (const r of raw) {
  const h = r.hook ?? r.title;
  if (!h) continue;
  byHook.set(h, [...(byHook.get(h) ?? []), r]);
}

function idFor(entry: { slug: string; hook: string }): string | null {
  const cands = byHook.get(entry.hook) ?? [];
  if (cands.length === 1) return cands[0].id ?? null;
  const bySlug = cands.find((c) => c.slug === entry.slug);
  if (bySlug) return bySlug.id ?? null;
  const bySuffix = cands.find((c) => c.id && entry.slug.endsWith(String(c.id).replace(/^[a-z]+-/, "")));
  return (bySuffix ?? cands[0])?.id ?? null;
}

const entries = archive.entries.map((e: { slug: string; hook: string }) => ({ ...e, clipId: idFor(e) }));

process.stdout.write(
  JSON.stringify({
    publication: String(COPY.handle).replace(/^@/, ""),
    site: COPY.site,
    total: archive.total,
    published: archive.published,
    entries,
  }),
);
